    public static boolean send(MountRosterAction action, MountRosterSource source, UUID targetUuid, int sourceSlot, int teamIndex) {
        if (action == null || source == null || targetUuid == null || ModNetwork.channel == null) {
            return false;
        }
        if (pending != null && !pending.terminal() && ClientMountRosterTransactionState.pending.source == source && ClientMountRosterTransactionState.pending.targetUuid.equals(targetUuid) && ClientMountRosterTransactionState.pending.action == action) {
            return false;
        }
        UUID requestId = UUID.randomUUID();
        if (action == MountRosterAction.ACTIVATE) {
            LocalPlayer player = Minecraft.m_91087_().f_91074_;
            if (player != null && player.m_20202_() != null && !targetUuid.equals(player.m_20202_().m_20148_())) {
                CompanionDetailPreviewRenderer.suppressLiveMirror(player.m_20202_().m_20148_());
            }
        } else if (action == MountRosterAction.RECALL) {
            CompanionDetailPreviewRenderer.suppressLiveMirror(targetUuid);
        }
        pending = new Pending(requestId, action, source, targetUuid, false);
        if (action == MountRosterAction.ACTIVATE) {
            ClientCameraLock.arm();
        }
        ModNetwork.sendToServer(new MountRosterIntentPacket(requestId, action, source, targetUuid, sourceSlot, teamIndex, ClientMountRosterTransactionState.expectedRevision(source)));
        return true;
    }

    public static void acceptResult(MountRosterIntentResultPacket packet) {
        if (packet == null || pending == null || !ClientMountRosterTransactionState.matches(ClientMountRosterTransactionState.pending.requestId, ClientMountRosterTransactionState.pending.action, ClientMountRosterTransactionState.pending.source, ClientMountRosterTransactionState.pending.targetUuid, packet)) {
            return;
        }
        if (packet.phase().terminal()) {
            pending = new Pending(packet.requestId(), packet.action(), packet.destinationSource(), packet.targetUuid(), true);
            if (packet.phase() != WheelIntentPhase.COMPLETED) {
                ClientMountRosterState.reset();
            }
        }
    }

    static boolean matches(UUID requestId, MountRosterAction action, MountRosterSource source, UUID targetUuid, MountRosterIntentResultPacket packet) {
        return packet != null && requestId != null && requestId.equals(packet.requestId()) && action == packet.action() && source == packet.destinationSource() && targetUuid != null && targetUuid.equals(packet.targetUuid());
    }

    public static boolean switching(MountRosterSource source, UUID targetUuid) {
        return pending != null && !ClientMountRosterTransactionState.pending.terminal && ClientMountRosterTransactionState.pending.action == MountRosterAction.ACTIVATE && ClientMountRosterTransactionState.pending.source == source && ClientMountRosterTransactionState.pending.targetUuid.equals(targetUuid);
    }

    public static boolean inProgress(MountRosterSource source, UUID targetUuid) {
        return pending != null && !ClientMountRosterTransactionState.pending.terminal && ClientMountRosterTransactionState.pending.source == source && ClientMountRosterTransactionState.pending.targetUuid.equals(targetUuid);
    }

    public static void reset() {
        pending = null;
    }

    private static long expectedRevision(MountRosterSource source) {
        return switch (source) {
            default -> throw new IncompatibleClassChangeError();
            case MountRosterSource.FIND_ME -> ClientCompanionState.serverRevision(CompanionKind.MOUNT);
            case MountRosterSource.VEHICLE -> ClientVehicleState.serverRevision();
        };
    }

    private record Pending(UUID requestId, MountRosterAction action, MountRosterSource source, UUID targetUuid, boolean terminal) {
    }
}

