        remembered = Mode.MOUNT;
    }

    public static void rememberVehicle() {
        remembered = Mode.VEHICLE;
    }

    public static boolean vehicleSelected() {
        return remembered == Mode.VEHICLE;
    }

    public static Screen createScreen() {
        boolean mountRidden;
        boolean vehicleRidden = ClientVehicleState.allEntries().stream().anyMatch(entry -> entry.ridden());
        return ClientMountWheelModeState.resolve(vehicleRidden, mountRidden = ClientCompanionState.allEntries(CompanionKind.MOUNT).stream().anyMatch(entry -> entry.ridden()), remembered) == Mode.VEHICLE ? new VehicleWheelScreen() : new CompanionWheelScreen(CompanionKind.MOUNT);
    }

    static Mode resolve(boolean vehicleRidden, boolean mountRidden, Mode remembered) {
        if (vehicleRidden != mountRidden) {
            return vehicleRidden ? Mode.VEHICLE : Mode.MOUNT;
        }
        return remembered == null ? Mode.MOUNT : remembered;
    }

    public static void reset() {
        remembered = Mode.MOUNT;
    }

    static enum Mode {
        MOUNT,
        VEHICLE;

    }
}

