        ArrayList<PackAnimationPresetListPacket.Entry> merged = new ArrayList<PackAnimationPresetListPacket.Entry>(entries);
        HashMap<String, Integer> positions = new HashMap<String, Integer>();
        for (int i = 0; i < merged.size(); ++i) {
            positions.put(merged.get(i).entityType(), i);
        }
        for (PackAnimationPresetListPacket.Entry entry : changedEntries) {
            Integer position = (Integer)positions.get(entry.entityType());
            if (position == null) {
                positions.put(entry.entityType(), merged.size());
                merged.add(entry);
                continue;
            }
            merged.set(position, entry);
        }
        entries = List.copyOf(merged);
    }

    public static List<PackAnimationPresetListPacket.Entry> entries() {
        return entries;
    }

    static {
        entries = List.of();
    }
}

